Here's a Python implementation of a trie data structure with insert, search, and prefix-based autocomplete functionality:

```python
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False
        self.word = None  # Store the complete word at the end node


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        """
        Insert a word into the trie.
        """
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True
        node.word = word

    def search(self, word: str) -> bool:
        """
        Search for a word in the trie. Returns True if found, False otherwise.
        """
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end

    def starts_with(self, prefix: str) -> bool:
        """
        Check if there is any word in the trie that starts with the given prefix.
        """
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

    def _dfs_collect_words(self, node: TrieNode, words: list) -> None:
        """
        Depth-first search to collect all words from a given node.
        Stops collecting when we have 3 words.
        """
        if len(words) >= 3:
            return

        if node.is_end:
            words.append(node.word)

        if len(words) >= 3:
            return

        # Iterate through children in alphabetical order
        for char in sorted(node.children.keys()):
            self._dfs_collect_words(node.children[char], words)
            if len(words) >= 3:
                break

