```rust
use std::cell::RefCell;
use std::rc::Rc;

// Definition for a binary tree node
#[derive(Debug, PartialEq, Eq)]
pub struct TreeNode {
    pub val: i32,
    pub left: Option<Rc<RefCell<TreeNode>>>,
    pub right: Option<Rc<RefCell<TreeNode>>>,
}

impl TreeNode {
    #[inline]
    pub fn new(val: i32) -> Self {
        TreeNode {
            val,
            left: None,
            right: None,
        }
    }
}

pub struct Codec;

impl Codec {
    const SENTINEL: &'static str = "null";
    const DELIMITER: &'static str = ",";

    pub fn new() -> Self {
        Codec
    }

    // Serializes a tree to a string
    pub fn serialize(&self, root: Option<Rc<RefCell<TreeNode>>>) -> String {
        let mut result = Vec::new();
        self.serialize_helper(root, &mut result);
        result.join(Self::DELIMITER)
    }

    fn serialize_helper(
        &self,
        node: Option<Rc<RefCell<TreeNode>>>,
        result: &mut Vec<String>,
    ) {
        match node {
            Some(node_ref) => {
                let node = node_ref.borrow();
                // Preorder traversal: root, left, right
                result.push(node.val.to_string());
                self.serialize_helper(node.left.clone(), result);
                self.serialize_helper(node.right.clone(), result);
            }
            None => {
                result.push(Self::SENTINEL.to_string());
            }
        }
    }

    // Deserializes a string back to a tree
    pub fn deserialize(&self, data: String) -> Option<Rc<RefCell<TreeNode>>> {
        if data.is_empty() {
            return None;
        }

        let values: Vec<String> = data
            .split(Self::DELIMITER)
            .map(|s| s.to_string())
            .collect();
        let mut index = 0;
        self.deserialize_helper(&values, &mut index)
    }

