// rateLimiter.js
class RateLimiter {
  constructor(options = {}) {
    this.windowSize = options.windowSize || 1000; // 1 second in ms
    this.maxRequests = options.maxRequests || 5;
    this.clients = new Map();

    // Clean up old entries every minute
    setInterval(() => this.cleanup(), 60000);
  }

  middleware() {
    return (req, res, next) => {
      const ip = req.ip || req.connection.remoteAddress;
      const now = Date.now();

      // Get or create client entry
      if (!this.clients.has(ip)) {
        this.clients.set(ip, {
          timestamps: []
        });
      }

      const client = this.clients.get(ip);

      // Remove timestamps outside the current window
      client.timestamps = client.timestamps.filter(
        timestamp => now - timestamp < this.windowSize
      );

      // Check if request is allowed
      if (client.timestamps.length >= this.maxRequests) {
        const oldestTimestamp = client.timestamps[0];
        const retryAfter = Math.ceil(
          (this.windowSize - (now - oldestTimestamp)) / 1000
        );

        return res.status(429).json({
          error: 'Too many requests',
          message: `Rate limit exceeded. Try again in ${retryAfter} seconds`,
          retryAfter: retryAfter
        });
      }

      // Add current timestamp
      client.timestamps.push(now);

      // Add rate limit headers
      res.setHeader('X-RateLimit-Limit', this.maxRequests);
      res.setHeader('X-RateLimit-Remaining', 
        this.maxRequests - client.timestamps.length
      );
      res.setHeader('X-RateLimit-Reset', 
        Math.ceil((now + this.windowSize) / 1000)
      );

      next();
    };
  }

