        std::cout << "Resource " << id_ << " created\n";
    }
    ~Resource() {
        std::cout << "Resource " << id_ << " destroyed\n";
    }
    void use() {
        std::cout << "Using resource " << id_ << "\n";
    }
private:
    int id_;
};

class Container {
public:
    Container() : resource_(nullptr) {}

    void createResource(int id) {
        if (resource_) {
            delete resource_;  // Manual cleanup
        }
        resource_ = new Resource(id);  // Raw allocation
    }

    Resource* getResource() {
        return resource_;
    }

    ~Container() {
        delete resource_;  // Manual cleanup - easy to forget!
    }

private:
    Resource* resource_;  // Raw pointer - ownership unclear
};

void processResource(Resource* res) {
    if (res) {
        res->use();
    }
}

int main() {
    Container container;
    container.createResource(1);
    processResource(container.getResource());

    // Potential issue: what if exception occurs?
    // Memory leak if Container destructor not called

    return 0;
}
