async function* streamResults(urls, concurrency = 3) {
  const executing = new Map();

  function startNext(url) {
    const promise = fetch(url).then(async response => {
      // Stream JSON in chunks for large responses
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let result = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        result += decoder.decode(value, { stream: true });
      }

      return { url, data: JSON.parse(result) };
    });

    executing.set(url, promise);
    return promise;
  }

  const iterator = urls[Symbol.iterator]();

  // Start initial batch
  for (let i = 0; i < concurrency; i++) {
    const { value, done } = iterator.next();
    if (done) break;
    startNext(value);
  }

  // Yield results as they complete, starting new ones
  while (executing.size > 0) {
    const { url, data } = await Promise.race(executing.values());
    executing.delete(url);
    yield { url, data };

    const { value, done } = iterator.next();
    if (!done) startNext(value);
  }
}

